BEGIN TRANSACTION;
CREATE TABLE "calendar_days" ("id" TEXT PRIMARY KEY NOT NULL,"calendar_id" TEXT NOT NULL REFERENCES "calendars"(id) DEFERRABLE INITIALLY DEFERRED,"date" TEXT NOT NULL,"weekday" INTEGER NOT NULL,"is_workday" INTEGER NOT NULL CHECK("is_workday" IN (0,1)),"day_type" TEXT NOT NULL CHECK("day_type" IN ('default_workday','default_weekend','holiday','makeup_workday','company_override')),"label" TEXT,"source_url" TEXT,"verified_at" TEXT,"verification_status" TEXT NOT NULL DEFAULT 'default_unverified' CHECK("verification_status" IN ('default_unverified','draft','verified')),"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),UNIQUE("calendar_id","date"));
CREATE TABLE "calendar_overrides" ("id" TEXT PRIMARY KEY NOT NULL,"calendar_id" TEXT NOT NULL REFERENCES "calendars"(id) DEFERRABLE INITIALLY DEFERRED,"date" TEXT NOT NULL,"person_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"is_workday" INTEGER NOT NULL CHECK("is_workday" IN (0,1)),"status" TEXT NOT NULL DEFAULT 'proposed' CHECK("status" IN ('proposed','confirmed','cancelled')),"reason" TEXT NOT NULL,"source_url" TEXT,"confirmed_at" TEXT,"confirmed_by_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "calendar_years" ("id" TEXT PRIMARY KEY NOT NULL,"calendar_id" TEXT NOT NULL REFERENCES "calendars"(id) DEFERRABLE INITIALLY DEFERRED,"year" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending' CHECK("status" IN ('pending','complete')),"source_url" TEXT,"published_on" TEXT,"verified_at" TEXT,"exception_hash" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),UNIQUE("calendar_id","year"));
CREATE TABLE "calendars" ("id" TEXT PRIMARY KEY NOT NULL,"name" TEXT NOT NULL,"timezone" TEXT NOT NULL DEFAULT 'Asia/Shanghai',"region" TEXT,"coverage_start" TEXT NOT NULL,"coverage_end" TEXT NOT NULL,"source_url" TEXT,"verified_at" TEXT,"notes" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "daily_confirmations" ("id" TEXT PRIMARY KEY NOT NULL,"project_id" TEXT NOT NULL REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"person_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"date" TEXT NOT NULL,"period" TEXT NOT NULL CHECK("period" IN ('AM','PM')),"work_location" TEXT NOT NULL DEFAULT 'unknown' CHECK("work_location" IN ('onsite','remote','travel','mixed','unknown')),"allocation_mode" TEXT NOT NULL DEFAULT 'unknown' CHECK("allocation_mode" IN ('dedicated','shared','unknown')),"available_hours" REAL,"project_hours" REAL,"operations_hours" REAL,"response_status" TEXT NOT NULL DEFAULT 'pending' CHECK("response_status" IN ('pending','confirmed','corrected')),"leave_plan_id" TEXT REFERENCES "leave_plans"(id) DEFERRABLE INITIALLY DEFERRED,"notes" TEXT,"future_leave_change" TEXT NOT NULL DEFAULT 'unknown' CHECK("future_leave_change" IN ('unknown','no_change','changed')),"future_leave_note" TEXT,"confirmed_at" TEXT,"confirmed_by_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"source" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),UNIQUE("project_id","person_id","date","period"));
CREATE TABLE "day_records" ("id" TEXT PRIMARY KEY NOT NULL,"person_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"calendar_id" TEXT NOT NULL REFERENCES "calendars"(id) DEFERRABLE INITIALLY DEFERRED,"date" TEXT NOT NULL,"period" TEXT NOT NULL CHECK("period" IN ('AM','PM')),"record_kind" TEXT NOT NULL CHECK("record_kind" IN ('planned','actual')),"status" TEXT NOT NULL CHECK("status" IN ('available','other_work','onsite','remote','travel','leave','off','unavailable','unknown')),"notes" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),UNIQUE("person_id","date","period","record_kind"));
CREATE TABLE "deliverables" ("id" TEXT PRIMARY KEY NOT NULL,"project_id" TEXT NOT NULL REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"work_item_id" TEXT NOT NULL REFERENCES "wbs"(id) DEFERRABLE INITIALLY DEFERRED,"title" TEXT NOT NULL,"document_url" TEXT,"document_id" TEXT REFERENCES "project_documents"(id) DEFERRABLE INITIALLY DEFERRED,"version_label" TEXT,"submitted_by_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"submitted_at" TEXT,"acceptor_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"acceptance_status" TEXT NOT NULL DEFAULT 'draft' CHECK("acceptance_status" IN ('draft','pending','accepted','rejected')),"reviewed_at" TEXT,"acceptance_comments" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "dependencies" ("id" TEXT PRIMARY KEY NOT NULL,"predecessor_id" TEXT NOT NULL REFERENCES "wbs"(id) DEFERRABLE INITIALLY DEFERRED,"successor_id" TEXT NOT NULL REFERENCES "wbs"(id) DEFERRABLE INITIALLY DEFERRED,"dependency_type" TEXT NOT NULL DEFAULT 'FS' CHECK("dependency_type" IN ('FS')),"lag_workdays" INTEGER NOT NULL DEFAULT 0,"notes" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),UNIQUE("predecessor_id","successor_id","dependency_type"));
CREATE TABLE event_log(event_id INTEGER PRIMARY KEY AUTOINCREMENT, transaction_id TEXT NOT NULL, recorded_at TEXT NOT NULL, actor TEXT NOT NULL, entity TEXT NOT NULL, record_id TEXT NOT NULL, before_json TEXT, after_json TEXT NOT NULL);
CREATE TABLE "interfaces" ("id" TEXT PRIMARY KEY NOT NULL,"name" TEXT NOT NULL,"project_id" TEXT NOT NULL REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"source_system" TEXT NOT NULL,"target_system" TEXT NOT NULL,"direction" TEXT NOT NULL DEFAULT 'outbound' CHECK("direction" IN ('outbound','inbound','bidirectional')),"protocol" TEXT NOT NULL DEFAULT 'http' CHECK("protocol" IN ('http','sftp','file','database','message','other')),"address" TEXT NOT NULL,"method" TEXT CHECK("method" IN ('GET','POST','PUT','PATCH','DELETE','SOAP','OTHER')),"description" TEXT NOT NULL,"owner_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"counterparty_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"status" TEXT NOT NULL DEFAULT 'designing' CHECK("status" IN ('designing','developing','testing','ready','blocked','retired')),"expected_ready" TEXT,"work_item_id" TEXT REFERENCES "wbs"(id) DEFERRABLE INITIALLY DEFERRED,"spec_url" TEXT,"auth_note" TEXT,"notes" TEXT,"operation_id" TEXT REFERENCES "operations"(id) DEFERRABLE INITIALLY DEFERRED,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "leave_plans" ("id" TEXT PRIMARY KEY NOT NULL,"project_id" TEXT NOT NULL REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"person_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"start_date" TEXT NOT NULL,"start_period" TEXT NOT NULL DEFAULT 'AM' CHECK("start_period" IN ('AM','PM')),"end_date" TEXT NOT NULL,"end_period" TEXT NOT NULL DEFAULT 'PM' CHECK("end_period" IN ('AM','PM')),"status" TEXT NOT NULL DEFAULT 'proposed' CHECK("status" IN ('proposed','confirmed','cancelled')),"backup_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"impact" TEXT,"source" TEXT,"confirmed_at" TEXT,"confirmed_by_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "meetings" ("id" TEXT PRIMARY KEY NOT NULL,"title" TEXT NOT NULL,"project_id" TEXT REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"service_id" TEXT REFERENCES "services"(id) DEFERRABLE INITIALLY DEFERRED,"organizer_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"scheduled_at" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'planned' CHECK("status" IN ('planned','held','cancelled')),"agenda" TEXT,"minutes" TEXT,"evidence" TEXT,"ends_at" TEXT,"attendee_ids" TEXT CHECK("attendee_ids" IS NULL OR (json_valid("attendee_ids") AND json_type("attendee_ids")='array')),"minutes_url" TEXT,"calendar_id" TEXT,"calendar_event_id" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "operations" ("id" TEXT PRIMARY KEY NOT NULL,"title" TEXT NOT NULL,"project_id" TEXT REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"service_id" TEXT REFERENCES "services"(id) DEFERRABLE INITIALLY DEFERRED,"work_type" TEXT NOT NULL DEFAULT 'request' CHECK("work_type" IN ('feature','improvement','bug','incident','request','action','configuration')),"stage" TEXT CHECK("stage" IN ('initiation','requirements','design','development','integration','testing','acceptance','launch','handover','other')),"forecast_start" TEXT,"forecast_finish" TEXT,"member_ids" TEXT CHECK("member_ids" IS NULL OR (json_valid("member_ids") AND json_type("member_ids")='array')),"backup_member_ids" TEXT CHECK("backup_member_ids" IS NULL OR (json_valid("backup_member_ids") AND json_type("backup_member_ids")='array')),"owner_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"acceptor_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"coordinator_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"actual_start" TEXT,"actual_finish" TEXT,"actual_person_days" REAL,"status" TEXT NOT NULL DEFAULT 'intake' CHECK("status" IN ('intake','ready','in_progress','blocked','in_review','done','cancelled')),"priority" TEXT CHECK("priority" IN ('P0','P1','P2','P3')),"urgency" TEXT CHECK("urgency" IN ('immediate','soon','normal')),"scope" TEXT NOT NULL DEFAULT 'operations' CHECK("scope" IN ('project','operations','adhoc')),"impact" TEXT CHECK("impact" IN ('critical','high','medium','low')),"severity" TEXT CHECK("severity" IN ('S1','S2','S3','S4')),"delay_risk" TEXT NOT NULL DEFAULT 'none' CHECK("delay_risk" IN ('none','at_risk')),"baseline_start" TEXT,"baseline_finish" TEXT,"next_action" TEXT,"next_due_at" TEXT,"waiting_on" TEXT,"blocker_reason" TEXT,"description" TEXT,"acceptance_criteria" TEXT,"completion_evidence" TEXT,"acceptance_standard" TEXT,"deliverable_spec" TEXT,"scope_note" TEXT,"priority_reason" TEXT,"delay_risk_reason" TEXT,"remediation_action" TEXT,"remediation_expected" TEXT,"remediation_actual" TEXT,"cancel_reason" TEXT,"reopen_reason" TEXT,"meeting_id" TEXT REFERENCES "meetings"(id) DEFERRABLE INITIALLY DEFERRED,"register_id" TEXT REFERENCES "registers"(id) DEFERRABLE INITIALLY DEFERRED,"baseline_change_id" TEXT REFERENCES "registers"(id) DEFERRABLE INITIALLY DEFERRED,"delay_reason" TEXT,"delay_impact" TEXT,"remediation_owner_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"remediation_result" TEXT,"decision_id" TEXT REFERENCES "registers"(id) DEFERRABLE INITIALLY DEFERRED,"source_url" TEXT,"progress_note" TEXT,"progress_confirmed_at" TEXT,"progress_confirmed_by_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"related_wbs_id" TEXT REFERENCES "wbs"(id) DEFERRABLE INITIALLY DEFERRED,"promoted_wbs_id" TEXT REFERENCES "wbs"(id) DEFERRABLE INITIALLY DEFERRED,"promoted_at" TEXT,"promotion_decision_id" TEXT REFERENCES "registers"(id) DEFERRABLE INITIALLY DEFERRED,"legacy_wbs_id" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "participants" ("id" TEXT PRIMARY KEY NOT NULL,"project_id" TEXT REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"work_item_id" TEXT REFERENCES "wbs"(id) DEFERRABLE INITIALLY DEFERRED,"person_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"role" TEXT NOT NULL CHECK("role" IN ('collaborator','interface','stakeholder','coordinator','backup')),"starts_on" TEXT,"ends_on" TEXT,"responsibility" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),UNIQUE("project_id","work_item_id","person_id","role","starts_on","ends_on"));
CREATE TABLE "people" ("id" TEXT PRIMARY KEY NOT NULL,"name" TEXT NOT NULL,"person_type" TEXT NOT NULL DEFAULT 'employee' CHECK("person_type" IN ('employee','vendor','external','unknown')),"company" TEXT,"department" TEXT,"project_role" TEXT,"expertise" TEXT,"phone" TEXT,"feishu_url" TEXT,"email" TEXT,"starts_on" TEXT,"ends_on" TEXT,"contact" TEXT,"backup_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"active" INTEGER NOT NULL DEFAULT 1 CHECK("active" IN (0,1)),"feishu_user_id" TEXT,"feishu_id_type" TEXT DEFAULT 'open_id' CHECK("feishu_id_type" IN ('open_id','user_id','union_id')),"identity_confirmed_at" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "project_documents" ("id" TEXT PRIMARY KEY NOT NULL,"title" TEXT NOT NULL,"project_id" TEXT NOT NULL REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"document_type" TEXT NOT NULL DEFAULT 'other' CHECK("document_type" IN ('charter','requirements','design','test','minutes','runbook','other')),"url" TEXT NOT NULL,"owner_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"status" TEXT NOT NULL DEFAULT 'draft' CHECK("status" IN ('draft','reviewing','approved','archived')),"version_label" TEXT,"updated_on" TEXT,"work_item_id" TEXT REFERENCES "wbs"(id) DEFERRABLE INITIALLY DEFERRED,"meeting_id" TEXT REFERENCES "meetings"(id) DEFERRABLE INITIALLY DEFERRED,"description" TEXT,"operation_id" TEXT REFERENCES "operations"(id) DEFERRABLE INITIALLY DEFERRED,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "projects" ("id" TEXT PRIMARY KEY NOT NULL,"name" TEXT NOT NULL,"project_type" TEXT NOT NULL DEFAULT 'development' CHECK("project_type" IN ('development','enhancement','migration','research','other')),"stage" TEXT NOT NULL DEFAULT 'initiating' CHECK("stage" IN ('initiating','planning','executing','accepting','closed','paused')),"po_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"pm_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"sponsor_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"service_id" TEXT REFERENCES "services"(id) DEFERRABLE INITIALLY DEFERRED,"calendar_id" TEXT NOT NULL REFERENCES "calendars"(id) DEFERRABLE INITIALLY DEFERRED,"goal" TEXT,"baseline_start" TEXT,"baseline_finish" TEXT,"forecast_finish" TEXT,"summary" TEXT,"business_impact" TEXT,"baseline_change_id" TEXT REFERENCES "registers"(id) DEFERRABLE INITIALLY DEFERRED,"reminder_start" TEXT,"reminder_end" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "registers" ("id" TEXT PRIMARY KEY NOT NULL,"kind" TEXT NOT NULL CHECK("kind" IN ('reminder','issue','risk','change','decision')),"title" TEXT NOT NULL,"project_id" TEXT REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"work_item_id" TEXT REFERENCES "wbs"(id) DEFERRABLE INITIALLY DEFERRED,"priority" TEXT DEFAULT 'P2' CHECK("priority" IN ('P0','P1','P2','P3')),"owner_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"coordinator_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"decision_by_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"impact" TEXT,"deadline_at" TEXT,"status" TEXT NOT NULL DEFAULT 'open' CHECK("status" IN ('open','in_review','approved','rejected','closed')),"proposal" TEXT,"next_action" TEXT,"decision" TEXT,"decided_at" TEXT,"closure_evidence" TEXT,"closed_at" TEXT,"operation_id" TEXT REFERENCES "operations"(id) DEFERRABLE INITIALLY DEFERRED,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "resource_weeks" ("id" TEXT PRIMARY KEY NOT NULL,"project_id" TEXT NOT NULL REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"person_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"week_start" TEXT NOT NULL,"net_available_hours" REAL,"project_hours" REAL,"operations_hours" REAL,"buffer_hours" REAL,"confirmed_at" TEXT,"confirmed_by_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"notes" TEXT,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0),UNIQUE("project_id","person_id","week_start"));
CREATE TABLE "services" ("id" TEXT PRIMARY KEY NOT NULL,"name" TEXT NOT NULL,"business_owner_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"technical_owner_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"calendar_id" TEXT NOT NULL REFERENCES "calendars"(id) DEFERRABLE INITIALLY DEFERRED,"description" TEXT,"active" INTEGER NOT NULL DEFAULT 1 CHECK("active" IN (0,1)),"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE snapshots(id TEXT PRIMARY KEY, label TEXT NOT NULL, created_at TEXT NOT NULL, cutoff TEXT NOT NULL, event_watermark INTEGER NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE "wbs" ("id" TEXT PRIMARY KEY NOT NULL,"node_kind" TEXT NOT NULL DEFAULT 'task' CHECK("node_kind" IN ('project','deliverable','module','task')),"parent_id" TEXT REFERENCES "wbs"(id) DEFERRABLE INITIALLY DEFERRED,"title" TEXT NOT NULL,"project_id" TEXT REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"service_id" TEXT REFERENCES "services"(id) DEFERRABLE INITIALLY DEFERRED,"work_type" TEXT NOT NULL DEFAULT 'request' CHECK("work_type" IN ('feature','improvement','bug','incident','request','action','configuration')),"stage" TEXT CHECK("stage" IN ('initiation','requirements','design','development','integration','testing','acceptance','launch','handover','other')),"is_acceptance_node" INTEGER NOT NULL DEFAULT 0 CHECK("is_acceptance_node" IN (0,1)),"forecast_start" TEXT,"forecast_finish" TEXT,"member_ids" TEXT CHECK("member_ids" IS NULL OR (json_valid("member_ids") AND json_type("member_ids")='array')),"backup_member_ids" TEXT CHECK("backup_member_ids" IS NULL OR (json_valid("backup_member_ids") AND json_type("backup_member_ids")='array')),"owner_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"acceptor_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"coordinator_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"actual_start" TEXT,"actual_finish" TEXT,"actual_person_days" REAL,"status" TEXT NOT NULL DEFAULT 'intake' CHECK("status" IN ('intake','ready','in_progress','blocked','in_review','done','cancelled')),"priority" TEXT CHECK("priority" IN ('P0','P1','P2','P3')),"urgency" TEXT CHECK("urgency" IN ('immediate','soon','normal')),"scope" TEXT NOT NULL DEFAULT 'project' CHECK("scope" IN ('project','operations','adhoc')),"impact" TEXT CHECK("impact" IN ('critical','high','medium','low')),"severity" TEXT CHECK("severity" IN ('S1','S2','S3','S4')),"delay_risk" TEXT NOT NULL DEFAULT 'none' CHECK("delay_risk" IN ('none','at_risk')),"baseline_start" TEXT,"baseline_finish" TEXT,"next_action" TEXT,"next_due_at" TEXT,"waiting_on" TEXT,"blocker_reason" TEXT,"description" TEXT,"acceptance_criteria" TEXT,"completion_evidence" TEXT,"acceptance_standard" TEXT,"deliverable_spec" TEXT,"scope_note" TEXT,"priority_reason" TEXT,"delay_risk_reason" TEXT,"remediation_action" TEXT,"remediation_expected" TEXT,"remediation_actual" TEXT,"cancel_reason" TEXT,"reopen_reason" TEXT,"meeting_id" TEXT REFERENCES "meetings"(id) DEFERRABLE INITIALLY DEFERRED,"register_id" TEXT REFERENCES "registers"(id) DEFERRABLE INITIALLY DEFERRED,"baseline_change_id" TEXT REFERENCES "registers"(id) DEFERRABLE INITIALLY DEFERRED,"delay_reason" TEXT,"delay_impact" TEXT,"remediation_owner_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"remediation_result" TEXT,"decision_id" TEXT REFERENCES "registers"(id) DEFERRABLE INITIALLY DEFERRED,"source_url" TEXT,"progress_note" TEXT,"progress_confirmed_at" TEXT,"progress_confirmed_by_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"migrated_operation_id" TEXT REFERENCES "operations"(id) DEFERRABLE INITIALLY DEFERRED,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
CREATE TABLE "weekly_commitments" ("id" TEXT PRIMARY KEY NOT NULL,"project_id" TEXT NOT NULL REFERENCES "projects"(id) DEFERRABLE INITIALLY DEFERRED,"work_item_id" TEXT REFERENCES "wbs"(id) DEFERRABLE INITIALLY DEFERRED,"operation_id" TEXT REFERENCES "operations"(id) DEFERRABLE INITIALLY DEFERRED,"week_start" TEXT NOT NULL,"outcome" TEXT NOT NULL,"due_date" TEXT NOT NULL,"owner_id" TEXT NOT NULL REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"verification" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'candidate' CHECK("status" IN ('candidate','confirmed','done','cancelled')),"confirmed_at" TEXT,"confirmed_by_id" TEXT REFERENCES "people"(id) DEFERRABLE INITIALLY DEFERRED,"completed_at" TEXT,"result_evidence" TEXT,"meeting_id" TEXT REFERENCES "meetings"(id) DEFERRABLE INITIALLY DEFERRED,"version" INTEGER NOT NULL DEFAULT 1 CHECK(version > 0));
DELETE FROM "sqlite_sequence";
COMMIT;
PRAGMA user_version=7;
